CREATE TYPE "public"."product_status" AS ENUM('draft', 'published', 'archived');--> statement-breakpoint
CREATE TABLE "products" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" varchar(200) NOT NULL,
	"slug" varchar(220) NOT NULL,
	"category" varchar(120) DEFAULT 'Заменители молока' NOT NULL,
	"description" text NOT NULL,
	"uses" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"composition" text DEFAULT '' NOT NULL,
	"preparation" text DEFAULT '' NOT NULL,
	"image_url" text,
	"status" "product_status" DEFAULT 'draft' NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	"featured" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX "products_slug_unique" ON "products" USING btree ("slug");--> statement-breakpoint
CREATE INDEX "products_status_idx" ON "products" USING btree ("status");--> statement-breakpoint
CREATE INDEX "products_sort_idx" ON "products" USING btree ("sort_order");--> statement-breakpoint
INSERT INTO "products" ("name", "slug", "category", "description", "uses", "composition", "preparation", "image_url", "status", "sort_order", "featured") VALUES
('ЗОМ «Агромилк»', 'zom-agromilk', 'Для поросят и КРС', 'Сухой молочный порошок с высоким содержанием протеина и сбалансированным витаминно-минеральным комплексом. Помогает постепенно переводить молодняк с молочного кормления на сухой рацион.', '["Выпаивание и выкармливание поросят", "Добавление в сухой корм поросятам и КРС"]'::jsonb, 'Молочная сыворотка, растительные и молочные белки, витаминно-минеральный комплекс. Точный состав и показатели партии указаны в сопроводительной документации.', 'Разводить чистой водой согласно инструкции к партии. Готовить только необходимый объём смеси и использовать свежеприготовленным.', '/assets/agromilk/product-scene-bag.webp', 'published', 10, true),
('ЗЦМ «Агромилк-2» 16%', 'zcm-agromilk-2-16', 'Для телят', 'Быстрорастворимый заменитель цельного молока с выраженным молочно-ванильным ароматом. Подходит для ручного выпаивания и автоматических кормовых станций.', '["Замена материнского молока со 2-й недели жизни", "Добавление в сухой корм КРС", "Использование в автоматической кормо-маме"]'::jsonb, 'Молочные компоненты, источники белка и жира, витаминно-минеральный комплекс. Массовая доля протеина — в соответствии со спецификацией продукта.', 'Порошок постепенно вносить в воду температурой 45–50 °C при постоянном перемешивании. Перед выпаиванием довести смесь до температуры 38–40 °C.', '/assets/agromilk/product-scene-bag.webp', 'published', 20, true),
('ЗЦМ «Агромилк-3» 11%', 'zcm-agromilk-3-11', 'Для телят', 'Растворимый молочный заменитель для стабильного роста молодняка. Смесь долго сохраняет однородность и хорошо поедается животными.', '["Выпаивание телят с 3-й недели жизни", "Добавление в сухой корм КРС"]'::jsonb, 'Молочная основа, растительные белки, жиры, витамины и микроэлементы. Подробные показатели приводятся в паспорте качества партии.', 'Смешивать с водой температурой 45–50 °C до однородности. Выпаивать при температуре, близкой к температуре молока.', '/assets/agromilk/product-scene-bag.webp', 'published', 30, false),
('ЗЦМ «Агромилк-4» 16%', 'zcm-agromilk-4-16', 'Для поросят', 'Питательная смесь для выпаивания поросят и использования в комбикормах. Выраженный аромат способствует хорошей поедаемости.', '["Выпаивание поросят", "Добавление в сухой корм КРС", "Замена молока свиноматки"]'::jsonb, 'Комбинация молочных и растительных компонентов, источников энергии, витаминов и минеральных веществ.', 'Готовить непосредственно перед кормлением. Соблюдать дозировку и температурный режим, указанные в инструкции к партии.', '/assets/agromilk/product-scene-bag.webp', 'published', 40, false),
('ЗЦМ «Агромилк-5» 12%', 'zcm-agromilk-5-12', 'Для телят', 'Экономичный заменитель молока для более поздних этапов выращивания телят. Поддерживает плавный переход к основному рациону.', '["Выпаивание телят с 5-й недели жизни", "Добавление в сухой корм КРС"]'::jsonb, 'Молочные и растительные компоненты, витаминно-минеральный комплекс. Конкретные показатели зависят от спецификации продукта.', 'Растворять в чистой воде при интенсивном перемешивании. Не хранить готовую смесь длительное время.', '/assets/agromilk/product-scene-bag.webp', 'published', 50, false)
ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "articles" ("title", "slug", "excerpt", "content", "cover_image_url", "status", "published_at") VALUES
('Как правильно приготовить заменитель молока', 'kak-prigotovit-zamenitel-moloka', 'Пошаговая инструкция по приготовлению смеси, выбору температуры воды и безопасному выпаиванию молодняка.', '<p>Правильное приготовление заменителя молока помогает сохранить питательную ценность смеси и обеспечить её хорошую поедаемость.</p><h2>Температура воды</h2><p>Для первичного растворения используйте чистую воду температурой 45–50 °C. Перед выпаиванием доведите готовую смесь до 38–40 °C.</p><h2>Порядок смешивания</h2><ol><li>Отмерьте необходимый объём воды.</li><li>Постепенно внесите порошок при постоянном перемешивании.</li><li>Перемешивайте до полного исчезновения комков.</li><li>Проверьте температуру перед кормлением.</li></ol><blockquote><p>Готовьте только тот объём смеси, который будет использован во время текущего кормления.</p></blockquote>', '/assets/agromilk/product-scene-bag.webp', 'published', now()),
('Таблица дозировки по возрасту животного', 'dozirovka-po-vozrastu', 'Основные принципы расчёта объёма смеси с учётом возраста, массы и состояния молодняка.', '<p>Дозировка зависит от возраста, живой массы, состояния здоровья и схемы кормления в хозяйстве.</p><h2>Основные правила</h2><ul><li>Не меняйте концентрацию смеси резко.</li><li>Увеличивайте объём постепенно.</li><li>Контролируйте потребление воды и основного корма.</li><li>При расстройствах пищеварения обратитесь к ветеринарному специалисту.</li></ul><p>Точные нормы для конкретного продукта указаны в инструкции и паспорте качества партии.</p>', '/assets/agromilk/hero-animals-desktop.webp', 'published', now()),
('Какой должна быть температура готовой смеси', 'temperatura-gotovoy-smesi', 'Почему температурный режим влияет на растворимость продукта, пищеварение и поедаемость.', '<p>Оптимальная температура готовой смеси перед выпаиванием обычно составляет 38–40 °C.</p><h2>Почему это важно</h2><p>Слишком холодная смесь хуже поедается и может вызвать переохлаждение. Слишком горячая вода способна снижать качество отдельных питательных компонентов.</p><h2>Как контролировать</h2><p>Используйте чистый пищевой термометр и проверяйте температуру непосредственно перед выпаиванием.</p>', '/assets/agromilk/consulting.webp', 'published', now()),
('Как перевести телёнка на ЗЦМ', 'perevod-telenka-na-zcm', 'Плавный переход на заменитель молока без резкого изменения рациона и лишнего стресса.', '<p>Переход на заменитель цельного молока проводят постепенно, контролируя аппетит, консистенцию кала и общее состояние телёнка.</p><h2>Пошаговая схема</h2><ol><li>В первые кормления замените небольшую часть цельного молока готовой смесью.</li><li>В течение нескольких дней постепенно увеличивайте долю ЗЦМ.</li><li>Сохраняйте одинаковое время кормления и температуру смеси.</li><li>Обеспечьте постоянный доступ к чистой воде.</li></ol>', '/assets/agromilk/hero-animals-mobile.webp', 'published', now())
ON CONFLICT ("slug") DO NOTHING;
